# 3dof Pitch,roll,yaw feadback feedforward adaptive controller for a quadcopter drone using leakage modification
import numpy as np
import control as ct
import matplotlib.pyplot as plt

# ============================================
# SYSTEM PARAMETERS (from your drone)
# ============================================

dt = 0.006  # Time step
ft = 100 # Simulation duration

# Approximate moments of inertia 
Jx = 0.01   # Roll moment of inertia [kg·m²]
Jy = 0.01   # Pitch moment of inertia [kg·m²]  
Jz = 0.02   # Yaw moment of inertia [kg·m²]

Lambda_true = np.diag([1/Jx, 1/Jy, 1/Jz])  # True inertia matrix [100, 100, 50]

# ============================================
# REFERENCE MODEL DESIGN
# ============================================
wn = 2.0 # Natural frequency [rad/s]
zeta = 0.8 # Damping ratio

Am_single_axis = np.array([[0, 1],
                    [-wn**2, -2*zeta*wn]])
Bm_single_axis = np.array([[0], 
                    [wn**2]])

Am = np.block([
    [Am_single_axis, np.zeros((2, 4))],
    [np.zeros((2,2)), Am_single_axis, np.zeros((2,2))],
    [np.zeros((2,4)), Am_single_axis]
               ])
Bm = np.block([
    [Bm_single_axis, np.zeros((2,2))],
    [np.zeros((2,1)), Bm_single_axis, np.zeros((2,1))],
    [np.zeros((2,2)), Bm_single_axis]
    ])

# ============================================
# Nominal Controller Design
# ============================================

A_single_axis = np.array([[0, 1],
                          [0, 0]])  
B_single_axis = np.array([[0], 
                          [1]])
C_single_axis = np.array([[1, 0]])

A_full = np.block([
    [A_single_axis, np.zeros((2,4))],
    [np.zeros((2,2)), A_single_axis, np.zeros((2,2))],
    [np.zeros((2,4)), A_single_axis]
])

B_full = np.block([
    [B_single_axis, np.zeros((2,2))],
    [np.zeros((2,1)), B_single_axis, np.zeros((2,1))],
    [np.zeros((2,2)), B_single_axis]
])

B_eff_pitch = B_single_axis / Jx
B_eff_roll = B_single_axis / Jy
B_eff_yaw = B_single_axis / Jz

K1_pitch = (np.linalg.pinv(B_eff_pitch) @ (A_single_axis - Am_single_axis)).flatten()
K2_pitch = (np.linalg.pinv(B_eff_pitch) @ Bm_single_axis).item()

K1_yaw = (np.linalg.pinv(B_eff_yaw) @ (A_single_axis - Am_single_axis)).flatten()
K2_yaw = (np.linalg.pinv(B_eff_yaw) @ Bm_single_axis).item()

K1_roll = (np.linalg.pinv(B_eff_roll) @ (A_single_axis - Am_single_axis)).flatten()
K2_roll = (np.linalg.pinv(B_eff_roll) @ Bm_single_axis).item()

print("Controller Gains (for u = -K1*x + K2*r):")
print(f"  Pitch/Roll: K1={K1_pitch}, K2={K2_pitch}")
print(f"  Yaw: K1={K1_yaw}, K2={K2_yaw}")

K1 = np.vstack([
    np.concatenate([K1_pitch, np.zeros(4)]),
    np.concatenate([np.zeros(2), K1_roll, np.zeros(2)]),
    np.concatenate([np.zeros(4), K1_yaw])
])
K2 = np.diag([K2_pitch, K2_roll, K2_yaw])

# Closed-loop A matrix (this is what the system actually achieves)
A_cl = A_full - B_full @ Lambda_true @ K1
eigs = np.linalg.eigvals(A_cl)
print(f"\n✓ Closed-loop eigenvalues: {eigs}")
print(f"✓ Reference model eigenvalues: {np.linalg.eigvals(Am_single_axis)}")
print(f"✓ All stable: {np.all(np.real(eigs) < 0)}")

# ============================================
# LYAPUNOV MATRIX - computed for the CLOSED-LOOP system
# ============================================
P_single_axis = ct.lyap(Am_single_axis.T, np.eye(2))
# >> Controller Gains (for u = -K1*x + K2*r):
# >>   Pitch/Roll: K1=[0.04  0.032], K2=0.04
# >>   Yaw: K1=[0.08  0.064], K2=0.08
# >>
# >> ✓ Closed-loop eigenvalues: [-1.6+1.2j -1.6-1.2j -1.6+1.2j -1.6-1.2j -1.6+1.2j -1.6-1.2j]
# >> ✓ Reference model eigenvalues: [-1.6+1.2j -1.6-1.2j]
# >> ✓ All stable: True

