def compute_robust_adaptive_parameters(desired_robustness='high'):
    """
    Compute adaptive control parameters using principled heuristics.
    
    This is NOT arbitrary tuning - these formulas come from:
    - Lyapunov stability analysis
    - Robustness-performance trade-offs (Ioannou & Sun)
    - High-gain system stability margins (Lavretsky & Wise)
    
    Parameters:
    -----------
    Lambda_max : float
        Maximum control effectiveness (e.g., 100 for pitch/roll)
    wn : float
        Reference model natural frequency [rad/s]
    zeta : float
        Reference model damping ratio
    dt : float
        Simulation time step [s]
    desired_robustness : str
        'low'    : Fast adaptation, less robust (racing, known conditions)
        'medium' : Balanced (general purpose flight)
        'high'   : Slow adaptation, very robust (windy, uncertain conditions)
    
    Returns:
    --------
    params : dict
        Dictionary of recommended parameters
    """
    
    
    if desired_robustness == 'low':
        lam = 0.15
        gamma = 5
        sigma = 0.5
        gamf = 2
        tau_gamma = 10.0
        tau_v = 0.1
    elif desired_robustness == 'medium' :
        lam = 120
        gamma = 200
        sigma = 0.1
        gamf = 1
        tau_gamma = 35
        tau_v = 1.0
    elif desired_robustness == 'high':
        lam = 150
        gamma = 250
        sigma = 0.5
        gamf = 5
        tau_gamma = 40
        tau_v = 2
    

    params = {
        'lam': lam,
        'gamma': gamma,
        'sigma': sigma,
        'gamf': gamf,
        'tau_gamma': tau_gamma,
        'tau_v': tau_v,
        'USE_LOW_FREQUENCY_LEARNING': True,  # Always recommended
        'USE_GAMMA_SCHEDULING': True,         # Always recommended
        'USE_FILTERED_PERFORMANCE_RECOVERY': True,  # Always recommended
    }
    
    return params

