def get_scheduled_gamma(t, gamma_final, tau):
    """
    Exponential gamma scheduling - theoretically sound approach.
    
    This is NOT clipping. Time-varying gains are well-established in 
    adaptive control theory (see Ioannou & Sun, Ch. 8).
    
    As t → ∞, gamma → gamma_final (recovers original adaptive law)
    """
    return gamma_final * (1.0 - np.exp(-t / tau))

def compute_basis(bias, angle, angle_rate, gyroscopic_coupling):
    """Base basis functions (uncertainty structure)"""
    theta = np.array([
        [bias],
        [angle],
        [angle_rate],
        [angle_rate * np.tanh(angle_rate)],
        [np.sin(angle)],
        [gyroscopic_coupling]
        ]) 
    return theta

def compute_extended_regressor(theta_base, un_axis, v_axis):
    """
    Extended regressor including control terms for Λ compensation.
    
    Theory: If true dynamics are ẍ = Λ(u + Δ), the adaptive control can be:
        ua = -Ŵ_Δᵀθ - Ŵ_Λᵀ[un; v]
    
    This allows adaptation to BOTH:
    1. Matched uncertainty Δ (via θ)
    2. Control effectiveness error (Λ - Λ_nom) (via un, v terms)
    """
    return np.vstack([theta_base, [[un_axis]], [[v_axis]]])


def compute_time_varying_uncertainty(t, x, level='easy'):
    """
    Compute time-varying uncertainty weights for drone adaptive control.
    """
    # Extract states (convert from degrees to radians if needed)
    pitch, pitch_dot = x[0, 0], x[1, 0]
    roll, roll_dot = x[2, 0], x[3, 0]
    yaw, yaw_dot = x[4, 0], x[5, 0]
    
    # ========================================================================
    # LEVEL 1: SLOWLY-VARYING AERODYNAMIC DRAG (EASY)
    # ========================================================================
    if level.lower() in ['easy', '1', 'level1']:
        # Slow sinusoidal variation - much slower than reference model
        drag_factor = 0.1 + 0.05 * np.sin(0.2 * t)
        
        W_true_pitch = np.array([
            [0.1],                      # Constant bias
            [0.05],                     # Angle coupling
            [0.02 * drag_factor],       # Rate damping (slowly varying)
            [0.15 * drag_factor],       # Quadratic drag (slowly varying)
            [0.03],                     # Nonlinear sin term
            [0.08]                      # Gyroscopic coupling
        ])
        
        W_true_roll = np.array([
            [0.1],
            [0.05],
            [0.02 * drag_factor],
            [0.15 * drag_factor],
            [0.03],
            [0.07]
        ])
        
        W_true_yaw = np.array([
            [0.05],
            [0.08],
            [0.01 * drag_factor],
            [0.0],
            [0.02],
            [0.06]
        ])
    
    # ========================================================================
    # LEVEL 2: PAYLOAD MASS SHIFT (MEDIUM)
    # ========================================================================
    elif level.lower() in ['medium', '2', 'level2']:
        # Piecewise time-varying scenario with ramps
        if t < 30:
            mass_shift = 0.0
        elif t < 35:
            mass_shift = (t - 30) / 5.0  # Ramp up over 5s
        elif t < 60:
            mass_shift = 1.0              # Sustained shift
        elif t < 65:
            mass_shift = 1.0 - (t - 60) / 5.0  # Ramp down
        else:
            mass_shift = 0.0
        
        # Varying inertial coupling (affects gyroscopic terms)
        coupling_gain = 0.08 + 0.12 * mass_shift  # 0.08 → 0.20
        
        # Varying bias (center-of-mass offset)
        bias_offset = 0.15 * mass_shift  # 0 → 0.15
        
        W_true_pitch = np.array([
            [0.1 + bias_offset],          # Bias varies with CoM
            [0.05],
            [0.02],
            [0.15],
            [0.03 + 0.02 * mass_shift],   # Nonlinearity increases
            [coupling_gain]               # Gyro coupling changes significantly
        ])
        
        W_true_roll = np.array([
            [0.1 + bias_offset],
            [0.05],
            [0.02],
            [0.15],
            [0.03 + 0.02 * mass_shift],
            [coupling_gain]
        ])
        
        W_true_yaw = np.array([
            [0.05],
            [0.08 + 0.05 * mass_shift],   # Yaw inertia changes
            [0.01],
            [0.0],
            [0.02],
            [coupling_gain]
        ])
    
    # ========================================================================
    # LEVEL 3: AGGRESSIVE MANEUVERING (HARD)
    # ========================================================================
    elif level.lower() in ['hard', '3', 'level3']:
        # 1. High-frequency vibration (rotor imbalance)
        vibe = 0.02 * np.sin(15 * t)  # 15 rad/s (~2.4 Hz)
        
        # 2. State-dependent aerodynamics (vortex ring at high rates)
        pitch_rate_abs = np.abs(pitch_dot)
        roll_rate_abs = np.abs(roll_dot)
        
        # Sudden drag increase near stall (20 deg/s threshold)
        stall_effect_pitch = 0.3 if pitch_rate_abs > 20.0 * np.pi/180 else 0.0
        stall_effect_roll = 0.3 if roll_rate_abs > 20.0 * np.pi/180 else 0.0
        
        # 3. Time-varying + state-dependent coupling
        maneuver_phase = np.sin(0.5 * t)  # Slow maneuver profile
        dynamic_coupling = 0.08 + 0.15 * np.abs(maneuver_phase) * np.tanh(pitch_rate_abs)
        
        W_true_pitch = np.array([
            [0.1 + vibe],                                  # Vibration in bias
            [0.05 + 0.03 * np.sin(0.3 * t)],              # Slow angle dependence
            [0.02 + stall_effect_pitch],                   # Sudden nonlinearity
            [0.15 * (1 + 0.5 * np.abs(maneuver_phase))],  # Varying drag
            [0.03 + 0.04 * np.abs(np.sin(pitch))],        # State-dependent sine
            [dynamic_coupling]                             # Fast + slow coupling
        ])
        
        W_true_roll = np.array([
            [0.1 + vibe * 0.8],                            # Slightly different vibe
            [0.05 + 0.03 * np.sin(0.3 * t + 1.0)],        # Phase-shifted
            [0.02 + stall_effect_roll],
            [0.15 * (1 + 0.5 * np.abs(maneuver_phase))],
            [0.03 + 0.04 * np.abs(np.sin(roll))],
            [dynamic_coupling]
        ])
        
        W_true_yaw = np.array([
            [0.05],
            [0.08 + 0.06 * np.abs(maneuver_phase)],       # Yaw authority varies
            [0.01],
            [0.0],
            [0.02],
            [dynamic_coupling * 0.7]                       # Reduced yaw coupling
        ])
    
    else:
        raise ValueError(f"Invalid level '{level}'. Use 'easy', 'medium', or 'hard'")
    
    return W_true_pitch, W_true_roll, W_true_yaw

def compute_reference_trajectory(t, level='easy'):
    """
    Generate realistic time-varying reference trajectories for drone attitude control.
    """
    
    deg2rad = np.pi / 180.0
    
    # ========================================================================
    # LEVEL 1: SLOW STABILIZATION AND GENTLE TRANSITIONS (EASY)
    # ========================================================================
    if level in ['easy', '1', 'level1', 1]:
        # Smooth step sequence with long dwell times
        if t < 20:
            # Initial hover (level attitude)
            pitch = 0.0
            roll = 0.0
            yaw = 0.0
        elif t < 40:
            # Forward tilt (slow acceleration)
            pitch = 8.0 * deg2rad
            roll = 0.0
            yaw = 0.0
        elif t < 60:
            # Left tilt with slight yaw
            pitch = 0.0
            roll = -8.0 * deg2rad
            yaw = 10.0 * deg2rad
        elif t < 80:
            # Return to level
            pitch = 0.0
            roll = 0.0
            yaw = 0.0
        else:
            # Backward tilt
            pitch = -8.0 * deg2rad
            roll = 0.0
            yaw = 0.0
    
    # ========================================================================
    # LEVEL 2: DYNAMIC MANEUVERING - RECTANGULAR PATTERN (MEDIUM)
    # ========================================================================
    elif level in ['medium', '2', 'level2', 2]:
        # Simulates rectangular flight pattern with coordinated turns
        phase = t % 40  # 40-second cycle
        
        if phase < 8:
            # Leg 1: Forward flight (pitch forward, level roll)
            pitch = 12.0 * deg2rad
            roll = 0.0
            yaw = 0.0 * deg2rad
        elif phase < 10:
            # Turn 1: Right turn (reduce pitch, roll right, yaw right)
            transition = (phase - 8) / 2.0  # 0 → 1 over 2 seconds
            pitch = 12.0 * (1 - transition) * deg2rad
            roll = 15.0 * transition * deg2rad
            yaw = 45.0 * transition * deg2rad
        elif phase < 18:
            # Leg 2: Right strafe
            pitch = 0.0
            roll = 12.0 * deg2rad
            yaw = 90.0 * deg2rad
        elif phase < 20:
            # Turn 2: Transition to backward
            transition = (phase - 18) / 2.0
            pitch = -12.0 * transition * deg2rad
            roll = 12.0 * (1 - transition) * deg2rad
            yaw = 90.0 + 45.0 * transition * deg2rad
        elif phase < 28:
            # Leg 3: Backward flight
            pitch = -12.0 * deg2rad
            roll = 0.0
            yaw = 180.0 * deg2rad
        elif phase < 30:
            # Turn 3: Left turn
            transition = (phase - 28) / 2.0
            pitch = -12.0 * (1 - transition) * deg2rad
            roll = -15.0 * transition * deg2rad
            yaw = 180.0 + 45.0 * transition * deg2rad
        elif phase < 38:
            # Leg 4: Left strafe
            pitch = 0.0
            roll = -12.0 * deg2rad
            yaw = 270.0 * deg2rad
        else:
            # Turn 4: Return to start
            transition = (phase - 38) / 2.0
            pitch = 12.0 * transition * deg2rad
            roll = -12.0 * (1 - transition) * deg2rad
            yaw = 270.0 + 45.0 * transition * deg2rad
    
    # ========================================================================
    # LEVEL 3: AGGRESSIVE AEROBATIC FLIGHT (HARD)
    # ========================================================================
    elif level in ['hard', '3', 'level3', 3]:
        # Multi-frequency sinusoidal excitation
        # Simulates aggressive FPV racing or aerobatic maneuvers
        
        # Pitch: Fast oscillation (0.3 Hz) + slow trend (0.05 Hz)
        pitch = (15.0 * np.sin(0.3 * 2*np.pi * t) + 
                 8.0 * np.sin(0.05 * 2*np.pi * t)) * deg2rad
        
        # Roll: Different frequency (0.25 Hz) + amplitude modulation
        amplitude_mod = 1.0 + 0.3 * np.sin(0.08 * 2*np.pi * t)
        roll = 18.0 * amplitude_mod * np.sin(0.25 * 2*np.pi * t) * deg2rad
        
        # Yaw: Continuous spinning with varying rate
        yaw_rate = 30.0 + 20.0 * np.sin(0.1 * 2*np.pi * t)  # deg/s
        yaw = (yaw_rate * t) * deg2rad
        
        # Add sudden "flip" maneuvers every 15 seconds
        if int(t) % 15 == 0 and (t % 1.0) < 0.5:  # 0.5s flip window
            pitch = pitch + 30.0 * deg2rad * np.sin(10 * t)
    
    # ========================================================================
    # LEVEL 4: CHAOTIC/UNPREDICTABLE DISTURBANCE REJECTION (EXTREME)
    # ========================================================================
    elif level in ['extreme', '4', 'level4', 4]:
        # Combination of random walk, multi-frequency, and sudden disturbances
        # Simulates extreme turbulence or adversarial conditions
        
        # Pseudo-random component (deterministic but looks random)
        np.random.seed(int(t * 100) % 10000)  # Changes every 0.01s
        random_pitch = np.random.uniform(-5, 5) * deg2rad
        random_roll = np.random.uniform(-5, 5) * deg2rad
        random_yaw = np.random.uniform(-10, 10) * deg2rad
        
        # Multi-frequency sinusoidal base
        pitch_base = (12.0 * np.sin(0.4 * 2*np.pi * t) + 
                      6.0 * np.sin(0.7 * 2*np.pi * t) +
                      3.0 * np.sin(1.2 * 2*np.pi * t)) * deg2rad
        
        roll_base = (15.0 * np.sin(0.35 * 2*np.pi * t) + 
                     7.0 * np.sin(0.9 * 2*np.pi * t) +
                     4.0 * np.cos(1.5 * 2*np.pi * t)) * deg2rad
        
        yaw_base = (25.0 * np.sin(0.2 * 2*np.pi * t) +
                    15.0 * np.sin(0.5 * 2*np.pi * t)) * deg2rad
        
        # Sudden step disturbances every 10 seconds
        disturbance_pitch = 0.0
        disturbance_roll = 0.0
        if int(t) % 10 == 0 and (t % 1.0) < 1.0:
            disturbance_pitch = 20.0 * deg2rad * (1 - (t % 1.0))
            disturbance_roll = -15.0 * deg2rad * (1 - (t % 1.0))
        
        # Combine all components
        pitch = pitch_base + random_pitch + disturbance_pitch
        roll = roll_base + random_roll + disturbance_roll
        yaw = yaw_base + random_yaw
        
        # Saturation (physical limits)
        pitch = np.clip(pitch, -35 * deg2rad, 35 * deg2rad)
        roll = np.clip(roll, -35 * deg2rad, 35 * deg2rad)
        yaw = np.clip(yaw, -180 * deg2rad, 180 * deg2rad)
    
    else:
        raise ValueError(f"Invalid level '{level}'. Use 'easy', 'medium', 'hard', or 'extreme'")
    
    # Return as column vector
    return np.array([[pitch], [roll], [yaw]])

