# SIMULATION INITIALIZATION
# ============================================
x = np.zeros((6,1))
xm = np.zeros((6,1))
xr = np.zeros((6,1))

# True uncertainty weights (only for base basis - not control terms)
if not Time_varying_unc: 
    W_true_pitch = np.array([[0.1], [0.05], [0.02], [0.15], [0.03], [0.08]])
    W_true_roll = np.array([[0.1], [0.05], [0.02], [0.15], [0.03], [0.07]])
    W_true_yaw = np.array([[0.05], [0.08], [0.01], [0.0], [0.02], [0.06]])

x_rec, xm_rec, xr_rec, u_rec, t_rec = [], [], [], [], []
What_pitch_rec, What_roll_rec, What_yaw_rec = [], [], []
Whatf_pitch_rec, Whatf_roll_rec, Whatf_yaw_rec = [], [], []
theta_pitch_rec, theta_roll_rec, theta_yaw_rec = [], [], []
e_pitch_rec, e_roll_rec, e_yaw_rec = [], [], []
ua_pitch_rec, ua_roll_rec, ua_yaw_rec = [], [], []
unc_pitch_rec, unc_roll_rec, unc_yaw_rec = [], [], []
v_rec = []
un_rec = []

r_filtered = np.zeros((3, 1))

# Previous step control for regressor (to avoid algebraic loop)
un_prev = np.zeros(3)
v_prev = np.zeros((3, 1))

# ============================================
# MAIN SIMULATION LOOP
# ============================================

for t in np.arange(0, ft, dt):

    r = compute_reference_trajectory(t, level='medium')

    r_filtered = r_filtered + dt * 4.0 * (r - r_filtered)

    if Time_varying_unc :
            W_true_pitch, W_true_roll, W_true_yaw = compute_time_varying_uncertainty(
            t, x, level='easy')

    # ----- EXTRACT STATES -----
    pitch, pitch_dot = x[0, 0], x[1, 0]
    roll, roll_dot = x[2, 0], x[3, 0]
    yaw, yaw_dot = x[4, 0], x[5, 0]

    # ----- COMPUTE BASIS FUNCTIONS -----
    theta_pitch_base = compute_basis(1.0, pitch, pitch_dot, roll_dot * yaw_dot)
    theta_roll_base = compute_basis(1.0, roll, roll_dot, pitch_dot * yaw_dot)
    theta_yaw_base = compute_basis(1.0, yaw, yaw_dot, pitch_dot * roll_dot)

    # ----- PERFORMANCE RECOVERY -----
    if PERFORMANCE_RECOVERY_ON:
        e_state = x - xm
        
        if USE_SECOND_ORDER_PR_FILTER:
            # =====================================================
            # SECOND-ORDER CRITICALLY DAMPED FILTER (RECOMMENDED)
            # =====================================================
            # Dynamics: f̈ + 2ζλḟ + λ²f = λ²e
            # 
            # This provides:
            # - Controllable damping (ζ) independent of speed (λ)
            # - No overshoot when ζ ≥ 1.0
            # - Faster settling than first-order with same λ
            # =====================================================
            
            f_ddot = lam**2 * (e_state - f) - 2 * zeta_pr * lam * f_dot
            f_dot = f_dot + dt * f_ddot
            f = f + dt * f_dot
            
            # Compute v from filtered f
            g = lam * f + (Am - lam * np.eye(6)) @ e_state
            v = np.linalg.pinv(B_full) @ g
            
        else:
            # Original first-order filter
            f = f + dt * (-lam * (f - e_state))
            g = lam * f + (Am - lam * np.eye(6)) @ e_state
            v_raw = np.linalg.pinv(B_full) @ g
            
            if USE_FILTERED_PERFORMANCE_RECOVERY:
                # Optional additional low-pass filter on v
                v_filtered = v_filtered + dt * (v_raw - v_filtered) / tau_v
                v = v_filtered
            else:
                v = v_raw
    else:
        v = np.zeros((3, 1))

    # ----- BUILD REGRESSORS (use previous control to avoid algebraic loop) -----
    if INCLUDE_CONTROL_IN_REGRESSOR:
        # Extended regressor with control terms
        theta_pitch = compute_extended_regressor(theta_pitch_base, un_prev[0], v_prev[0, 0])
        theta_roll = compute_extended_regressor(theta_roll_base, un_prev[1], v_prev[1, 0])
        theta_yaw = compute_extended_regressor(theta_yaw_base, un_prev[2], v_prev[2, 0])
    else:
        # Base regressor only
        theta_pitch = theta_pitch_base
        theta_roll = theta_roll_base
        theta_yaw = theta_yaw_base

    # ----- ADAPTIVE CONTROL -----
    if ADAPTATION_ON:
        ua_pitch = -What_pitch.T @ theta_pitch
        ua_roll = -What_roll.T @ theta_roll
        ua_yaw = -What_yaw.T @ theta_yaw
        ua = np.array([ua_pitch.item(), ua_roll.item(), ua_yaw.item()])
    else:
        ua = np.zeros(3)
        ua_pitch = np.array([[0.0]])
        ua_roll = np.array([[0.0]])
        ua_yaw = np.array([[0.0]])

    # ----- NOMINAL CONTROL -----
    un_feedback = (-K1 @ x).flatten()
    un_feedforward = (K2 @ r_filtered).flatten()
    un = un_feedback + un_feedforward + v.flatten()

    # ----- TOTAL CONTROL -----
    u = un + ua

    # ----- STORE CURRENT CONTROL FOR NEXT STEP REGRESSOR -----
    un_prev = un.copy()
    v_prev = v.copy()

    # ----- REFERENCE MODEL UPDATE -----
    if PERFORMANCE_RECOVERY_ON:
        xm = xm + dt * (Am @ xm + Bm @ r_filtered + B_full @ v)
    else:
        xm = xm + dt * (Am @ xm + Bm @ r_filtered)
    xr = xr + dt * (Am @ xr + Bm @ r_filtered)

    # ----- TRACKING ERRORS -----
    e_pitch = np.array([[x[0,0] - xm[0,0]], [x[1,0] - xm[1,0]]])
    e_roll = np.array([[x[2,0] - xm[2,0]], [x[3,0] - xm[3,0]]])
    e_yaw = np.array([[x[4,0] - xm[4,0]], [x[5,0] - xm[5,0]]])

    # ----- ADAPTIVE LAW -----
    if ADAPTATION_ON:
        if USE_NORMILIZATION :
            norm_pitch = 1.0 + (theta_pitch.T @ theta_pitch).item()
            norm_roll = 1.0 + (theta_roll.T @ theta_roll).item()
            norm_yaw = 1.0 + (theta_yaw.T @ theta_yaw).item()
        else :
            norm_pitch = 1.0
            norm_roll = 1.0
            norm_yaw = 1.0
        
        grad_pitch = theta_pitch @ (e_pitch.T @ P_single_axis @ B_single_axis)
        grad_roll = theta_roll @ (e_roll.T @ P_single_axis @ B_single_axis)
        grad_yaw = theta_yaw @ (e_yaw.T @ P_single_axis @ B_single_axis)

        
        if USE_GAMMA_SCHEDULING:
            gamma = get_scheduled_gamma(t, gamma_final, tau_gamma)
        else:
            gamma = gamma_final

        if USE_LOW_FREQUENCY_LEARNING:
            # Low-frequency learning: σ-mod with filtered weights
            # ẆHat = γ(grad - σ(Ŵ - Ŵf)) / norm
            # Ẇf = γf(Ŵ - Ŵf)
            What_pitch = What_pitch + dt * gamma * (grad_pitch - sigma * (What_pitch - Whatf_pitch)) #/ norm_pitch
            What_roll = What_roll + dt * gamma * (grad_roll - sigma * (What_roll - Whatf_roll)) #/ norm_roll
            What_yaw = What_yaw + dt * gamma * (grad_yaw - sigma * (What_yaw - Whatf_yaw)) #/ norm_yaw
            
            # Update low-frequency weight filters
            Whatf_pitch = Whatf_pitch + dt * gamf * (What_pitch - Whatf_pitch)
            Whatf_roll = Whatf_roll + dt * gamf * (What_roll - Whatf_roll)
            Whatf_yaw = Whatf_yaw + dt * gamf * (What_yaw - Whatf_yaw)
        else:
            # Standard σ-modification (leakage to zero)
            What_pitch = What_pitch + dt * gamma * (grad_pitch - sigma * What_pitch) / norm_pitch
            What_roll = What_roll + dt * gamma * (grad_roll - sigma * What_roll) / norm_roll
            What_yaw = What_yaw + dt * gamma * (grad_yaw - sigma * What_yaw) / norm_yaw

    # ----- SYSTEM DYNAMICS -----
    # True uncertainty uses ONLY base basis (the uncertainty doesn't depend on control)
    unc_pitch = (W_true_pitch.T @ theta_pitch_base).item()
    unc_roll = (W_true_roll.T @ theta_roll_base).item()
    unc_yaw = (W_true_yaw.T @ theta_yaw_base).item()
    
    unc_vec = np.array([[unc_pitch], [unc_roll], [unc_yaw]])
    
    x = x + dt * (A_full @ x + B_full @ Lambda_true @ (u.reshape(-1,1) + unc_vec))

    # ----- RECORD DATA -----
    x_rec.append(x.flatten() * 180/np.pi)
    xm_rec.append(xm.flatten() * 180/np.pi)
    xr_rec.append(xr.flatten() * 180/np.pi)
    e_pitch_rec.append(e_pitch.flatten() * 180/np.pi)
    e_roll_rec.append(e_roll.flatten() * 180/np.pi)
    e_yaw_rec.append(e_yaw.flatten() * 180/np.pi)
    u_rec.append(u.flatten())
    t_rec.append(t)
    What_pitch_rec.append(What_pitch.flatten())
    What_roll_rec.append(What_roll.flatten())
    What_yaw_rec.append(What_yaw.flatten())
    theta_pitch_rec.append(theta_pitch.flatten())
    theta_roll_rec.append(theta_roll.flatten())
    theta_yaw_rec.append(theta_yaw.flatten())
    ua_pitch_rec.append(ua_pitch.item() if hasattr(ua_pitch, 'item') else ua_pitch)
    ua_roll_rec.append(ua_roll.item() if hasattr(ua_roll, 'item') else ua_roll)
    ua_yaw_rec.append(ua_yaw.item() if hasattr(ua_yaw, 'item') else ua_yaw)
    unc_pitch_rec.append(unc_pitch)
    unc_roll_rec.append(unc_roll)
    unc_yaw_rec.append(unc_yaw)
    v_rec.append(v.flatten())
    un_rec.append(un.flatten())

    if USE_LOW_FREQUENCY_LEARNING:
        Whatf_pitch_rec.append(Whatf_pitch.flatten())
        Whatf_roll_rec.append(Whatf_roll.flatten())
        Whatf_yaw_rec.append(Whatf_yaw.flatten())

print("✅ Simulation completed!")
print(f"Final time: {t:.2f}s")
print(f"Performance Recovery: {'ON' if PERFORMANCE_RECOVERY_ON else 'OFF'}")
print(f"Adaptation: {'ON' if ADAPTATION_ON else 'OFF'}")
print(f"Low-Frequency Learning: {'ON (γf=' + str(gamf) + ')' if USE_LOW_FREQUENCY_LEARNING else 'OFF (standard σ-mod)'}")
print(f"Control in Regressor: {'ON (Λ compensation enabled)' if INCLUDE_CONTROL_IN_REGRESSOR else 'OFF (base uncertainty only)'}")
print(f"Regressor size: {num_basis} elements")
