import numpy as np
from scipy import signal

def diagnose_adaptive_controller(t_rec, x_rec, xm_rec, u_rec, ua_pitch_rec, 
                                  ua_roll_rec, ua_yaw_rec, What_pitch_rec, 
                                  What_roll_rec, What_yaw_rec, e_pitch_rec, 
                                  e_roll_rec, e_yaw_rec, v_rec, 
                                  wn=None, zeta=None, lam=None, gamma=None, 
                                  sigma=None, tau_v=None):
    """
    🔬 THEORY-DRIVEN DIAGNOSTICS for Adaptive Controller Tuning
    
    This function provides ROOT CAUSE ANALYSIS by connecting observed symptoms 
    to fundamental theoretical properties:
    
    ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
    THEORETICAL FOUNDATION:
    ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
    
    1. REFERENCE MODEL (Desired Dynamics):
       ẍ_m + 2ζω_n ẋ_m + ω_n² x_m = ω_n² r
       
       → ω_n sets the SPEED of response (settling time ≈ 4/(ζω_n))
       → ζ sets the DAMPING (overshoot, oscillation)
       → This is YOUR TARGET - what you WANT the system to do
    
    2. ADAPTIVE LAW (Parameter Estimation):
       Ẇ = Γ[Φe^T P B - σW] / (1 + Φ^T Φ)
       
       → Γ (gamma) sets LEARNING RATE - how fast we estimate uncertainties
       → σ (sigma) adds DAMPING to prevent parameter drift/bursting
       → Trade-off: Fast learning (high Γ) ↔ Noise rejection (low Γ)
    
    3. PERFORMANCE RECOVERY FILTER (L1/Filtered Adaptive Control):
       v̇ = (1/τ_v)(v_desired - v)   [First-order]
       OR
       v̈ + 2ζ_pr λ v̇ + λ² v = λ² v_desired   [Second-order]
       
       ⚠️ CRITICAL: τ_v (or 1/λ) determines the bandwidth of the filter
       
       → τ_v TOO SMALL (high bandwidth): 
          • Filter does nothing → No separation between estimation & control
          • High-frequency noise/adaptation passes through → OSCILLATIONS
          • Can amplify unmodeled dynamics → INSTABILITY/OVERFLOW
       
       → τ_v TOO LARGE (low bandwidth): 
          • Over-filtering → Sluggish response, can't cancel fast disturbances
          • Large phase lag → Reduces stability margins
       
       → RULE: τ_v should filter OUT frequencies above ω_n (reference model)
                but PASS frequencies below ω_n
                Suggested: τ_v ≈ 0.5 to 2.0 seconds (cutoff ≈ 0.5-2 rad/s)
    
    4. FREQUENCY SEPARATION PRINCIPLE:
       For stability and good performance:
       
           ω_adaptation  >>  ω_reference  >>  ω_filter_cutoff  >>  0
           (fast learn)      (desired)        (v smoothing)
       
       Example: Γ=200 → bandwidth ≈√200≈14 rad/s
                ω_n=2 rad/s → reference bandwidth
                1/τ_v=0.5 rad/s (τ_v=2s) → filter cutoff
    
    ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
    
    Parameters:
    -----------
    ... (data arrays from simulation)
    wn : float - Reference model natural frequency [rad/s]
    zeta : float - Reference model damping ratio
    lam : float - Performance recovery bandwidth [rad/s] (if using 2nd-order)
    gamma : float - Final adaptation gain (learning rate)
    sigma : float - Sigma-modification gain (leakage)
    tau_v : float - Time constant for v filter [s] (if using 1st-order)
    
    Returns:
    --------
    diagnostics : dict - ROOT CAUSE analysis with targeted solutions
    """
    
    # Convert lists to arrays
    t = np.array(t_rec)
    x = np.array(x_rec)
    xm = np.array(xm_rec)
    u = np.array(u_rec)
    ua_pitch = np.array(ua_pitch_rec)
    ua_roll = np.array(ua_roll_rec)
    ua_yaw = np.array(ua_yaw_rec)
    What_pitch = np.array(What_pitch_rec)
    What_roll = np.array(What_roll_rec)
    What_yaw = np.array(What_yaw_rec)
    e_pitch = np.array(e_pitch_rec)
    e_roll = np.array(e_roll_rec)
    e_yaw = np.array(e_yaw_rec)
    v = np.array(v_rec)
    
    dt = np.mean(np.diff(t))
    
    diagnostics = {
        'issues': [],
        'recommendations': [],
        'metrics': {},
        'severity': 'HEALTHY'  # HEALTHY, WARNING, CRITICAL
    }
    
    # =========================================================================
    # 1. CHECK FOR NUMERICAL OVERFLOW/INSTABILITY
    # =========================================================================
    max_u = np.max(np.abs(u))
    max_ua = np.max([np.max(np.abs(ua_pitch)), np.max(np.abs(ua_roll)), np.max(np.abs(ua_yaw))])
    max_weight = np.max([np.max(np.abs(What_pitch)), np.max(np.abs(What_roll)), np.max(np.abs(What_yaw))])
    
    diagnostics['metrics']['max_control'] = max_u
    diagnostics['metrics']['max_adaptive_control'] = max_ua
    diagnostics['metrics']['max_weight'] = max_weight
    
    if max_u > 1e6 or np.any(np.isnan(u)) or np.any(np.isinf(u)):
        diagnostics['issues'].append("🚨 NUMERICAL OVERFLOW DETECTED in control signal u")
        diagnostics['recommendations'].append(
            "CRITICAL: Reduce γ (gamma) by 50-90%. Current adaptation is TOO FAST causing instability."
        )
        diagnostics['recommendations'].append(
            "CRITICAL: Increase σ (sigma) by 5-10x to add more damping (leakage)."
        )
        diagnostics['severity'] = 'CRITICAL'
    
    elif max_u > 1e3:
        diagnostics['issues'].append("⚠️ Very large control signals (>1000)")
        diagnostics['recommendations'].append(
            "WARNING: Reduce γ by 30-50%. High gains are amplifying noise or uncertainty."
        )
        diagnostics['severity'] = max(diagnostics['severity'], 'WARNING', key=['HEALTHY', 'WARNING', 'CRITICAL'].index)
    
    if max_weight > 1e3:
        diagnostics['issues'].append("⚠️ Adaptive weights growing unbounded")
        diagnostics['recommendations'].append(
            "Increase σ (sigma-modification) by 2-5x. Parameters are drifting."
        )
        diagnostics['recommendations'].append(
            "Check if regressor is persistently exciting (PE). Lack of PE causes drift."
        )
        diagnostics['severity'] = max(diagnostics['severity'], 'WARNING', key=['HEALTHY', 'WARNING', 'CRITICAL'].index)
    
    # =========================================================================
    # 2. TRACKING ERROR ANALYSIS
    # =========================================================================
    # Compute RMS tracking errors (degrees)
    e_pitch_rms = np.sqrt(np.mean(e_pitch[:, 0]**2))
    e_roll_rms = np.sqrt(np.mean(e_roll[:, 0]**2))
    e_yaw_rms = np.sqrt(np.mean(e_yaw[:, 0]**2))
    
    # Peak errors
    e_pitch_peak = np.max(np.abs(e_pitch[:, 0]))
    e_roll_peak = np.max(np.abs(e_roll[:, 0]))
    e_yaw_peak = np.max(np.abs(e_yaw[:, 0]))
    
    diagnostics['metrics']['rms_error_pitch'] = e_pitch_rms
    diagnostics['metrics']['rms_error_roll'] = e_roll_rms
    diagnostics['metrics']['rms_error_yaw'] = e_yaw_rms
    diagnostics['metrics']['peak_error_pitch'] = e_pitch_peak
    diagnostics['metrics']['peak_error_roll'] = e_roll_peak
    diagnostics['metrics']['peak_error_yaw'] = e_yaw_peak
    
    # Thresholds (degrees)
    POOR_RMS_THRESHOLD = 5.0  # degrees
    POOR_PEAK_THRESHOLD = 15.0  # degrees
    
    if e_pitch_rms > POOR_RMS_THRESHOLD or e_roll_rms > POOR_RMS_THRESHOLD:
        diagnostics['issues'].append(f"⚠️ Poor RMS tracking (Pitch: {e_pitch_rms:.2f}°, Roll: {e_roll_rms:.2f}°)")
        diagnostics['recommendations'].append(
            "Increase γ (gamma) by 50-100% for faster adaptation."
        )
        diagnostics['recommendations'].append(
            "Increase λ (lambda) by 20-50% to allow more aggressive cancellation."
        )
        diagnostics['severity'] = max(diagnostics['severity'], 'WARNING', key=['HEALTHY', 'WARNING', 'CRITICAL'].index)
    
    if e_pitch_peak > POOR_PEAK_THRESHOLD or e_roll_peak > POOR_PEAK_THRESHOLD:
        diagnostics['issues'].append(f"⚠️ Large transient errors (Pitch: {e_pitch_peak:.2f}°, Roll: {e_roll_peak:.2f}°)")
        diagnostics['recommendations'].append(
            "Enable or decrease tau_gamma (gamma scheduling) to allow faster initial adaptation."
        )
    
    # =========================================================================
    # 3. HIGH-FREQUENCY OSCILLATION DETECTION
    # =========================================================================
    # Compute power spectral density of control signal
    def detect_oscillations(signal_data, dt, axis_name):
        """Detect high-frequency oscillations using FFT"""
        if len(signal_data) < 100:
            return None
        
        # Detrend
        signal_detrended = signal_data - np.mean(signal_data)
        
        # FFT
        freqs, psd = signal.welch(signal_detrended, fs=1/dt, nperseg=min(512, len(signal_data)//4))
        
        # Find dominant frequency
        idx_max = np.argmax(psd[1:]) + 1  # Skip DC component
        dominant_freq = freqs[idx_max]
        dominant_power = psd[idx_max]
        
        # High-frequency threshold (above reference model bandwidth)
        hf_threshold = 5.0  # Hz (adjust based on wn)
        
        if dominant_freq > hf_threshold and dominant_power > 0.1 * np.max(psd):
            return {
                'freq': dominant_freq,
                'power': dominant_power,
                'axis': axis_name
            }
        return None
    
    osc_pitch = detect_oscillations(ua_pitch, dt, 'Pitch')
    osc_roll = detect_oscillations(ua_roll, dt, 'Roll')
    osc_yaw = detect_oscillations(ua_yaw, dt, 'Yaw')
    
    oscillations = [osc for osc in [osc_pitch, osc_roll, osc_yaw] if osc is not None]
    
    if oscillations:
        for osc in oscillations:
            diagnostics['issues'].append(
                f"⚠️ High-frequency oscillation detected in {osc['axis']} adaptive control: {osc['freq']:.2f} Hz"
            )
        diagnostics['recommendations'].append(
            "Reduce γ (gamma) by 30-50% to reduce high-frequency gain."
        )
        diagnostics['recommendations'].append(
            "Enable/Increase τ_v (tau_v) to add low-pass filtering on performance recovery."
        )
        diagnostics['recommendations'].append(
            "Enable LOW_FREQUENCY_LEARNING with γ_f ≈ 0.05*γ to suppress HF adaptation."
        )
        diagnostics['severity'] = max(diagnostics['severity'], 'WARNING', key=['HEALTHY', 'WARNING', 'CRITICAL'].index)
    
    # =========================================================================
    # 4. PARAMETER DRIFT DETECTION
    # =========================================================================
    def detect_drift(weights, axis_name):
        """Check if weights are monotonically growing (drift)"""
        # Compute trend (linear regression slope)
        t_norm = np.linspace(0, 1, len(weights))
        for i in range(weights.shape[1]):
            slope = np.polyfit(t_norm, weights[:, i], 1)[0]
            if abs(slope) > 10.0:  # Arbitrary threshold
                return True, i, slope
        return False, None, None
    
    drift_pitch, idx_p, slope_p = detect_drift(What_pitch, 'Pitch')
    drift_roll, idx_r, slope_r = detect_drift(What_roll, 'Roll')
    drift_yaw, idx_y, slope_y = detect_drift(What_yaw, 'Yaw')
    
    if drift_pitch or drift_roll or drift_yaw:
        diagnostics['issues'].append("⚠️ Parameter drift detected (weights growing without bound)")
        diagnostics['recommendations'].append(
            "Increase σ (sigma) by 2-5x to add more leakage/damping."
        )
        diagnostics['recommendations'].append(
            "Check persistent excitation: Is the reference trajectory rich enough?"
        )
        diagnostics['severity'] = max(diagnostics['severity'], 'WARNING', key=['HEALTHY', 'WARNING', 'CRITICAL'].index)
    
    # =========================================================================
    # 5. ADAPTATION SPEED ANALYSIS
    # =========================================================================
    # Check how long it takes for weights to converge (settle within 5% of final value)
    def settling_time(weights, threshold=0.05):
        """Estimate settling time for weight convergence"""
        final_vals = weights[-1000:].mean(axis=0)  # Average last part
        for i, final_val in enumerate(final_vals):
            if abs(final_val) < 0.01:  # Skip near-zero weights
                continue
            settling_idx = None
            for j in range(len(weights)):
                if abs(weights[j, i] - final_val) / (abs(final_val) + 1e-6) < threshold:
                    settling_idx = j
                    break
            if settling_idx and settling_idx > len(weights) * 0.5:  # Settles in 2nd half
                return settling_idx * dt, i
        return None, None
    
    ts_pitch, idx_slow_p = settling_time(What_pitch)
    ts_roll, idx_slow_r = settling_time(What_roll)
    
    if ts_pitch and ts_pitch > t[-1] * 0.7:
        diagnostics['issues'].append(f"⚠️ Slow adaptation: Weights settle after {ts_pitch:.1f}s (>70% of simulation)")
        diagnostics['recommendations'].append(
            "Increase γ (gamma) by 50-100% for faster convergence."
        )
        diagnostics['recommendations'].append(
            "Decrease tau_gamma (if using scheduling) to ramp up faster."
        )
    
    # =========================================================================
    # 6. PERFORMANCE RECOVERY ANALYSIS
    # =========================================================================
    v_norm = np.linalg.norm(v, axis=1)
    v_max = np.max(v_norm)
    v_rms = np.sqrt(np.mean(v_norm**2))
    
    diagnostics['metrics']['v_max'] = v_max
    diagnostics['metrics']['v_rms'] = v_rms
    
    if v_max > 100:
        diagnostics['issues'].append(f"⚠️ Very large performance recovery signal (max: {v_max:.1f})")
        diagnostics['recommendations'].append(
            "Reduce λ (lambda) by 30-50%. High PR gain is injecting excessive control."
        )
        diagnostics['severity'] = max(diagnostics['severity'], 'WARNING', key=['HEALTHY', 'WARNING', 'CRITICAL'].index)
    
    # =========================================================================
    # 7. CONTROL SATURATION CHECK
    # =========================================================================
    # Check if control is frequently saturating (clipping)
    # Assume reasonable limits: ±200 for attitude control
    SATURATION_LIMIT = 200
    saturation_rate = np.mean(np.abs(u) > SATURATION_LIMIT * 0.9)
    
    diagnostics['metrics']['saturation_rate'] = saturation_rate * 100  # Percent
    
    if saturation_rate > 0.1:  # >10% of time saturated
        diagnostics['issues'].append(f"⚠️ Control saturation detected {saturation_rate*100:.1f}% of time")
        diagnostics['recommendations'].append(
            "Reduce λ (lambda) and γ (gamma) by 20-40% to prevent windup."
        )
        diagnostics['recommendations'].append(
            "Add anti-windup logic to adaptive law (project weights)."
        )
    
    # =========================================================================
    # SUMMARY
    # =========================================================================
    if not diagnostics['issues']:
        diagnostics['issues'].append("✅ No major issues detected!")
        diagnostics['recommendations'].append("Controller is well-tuned for this scenario.")
    
    return diagnostics


