for i, axis_name in enumerate(axes_names):
    print(f"\n{axis_name} Axis:")
    print(f"  Max Angle Error:        {np.max(np.abs(angle_errors[i])):.3f}°")
    print(f"  Mean Angle Error:       {np.mean(np.abs(angle_errors[i])):.3f}°")
    print(f"  Final Angle Error:      {angle_errors[i][-1]:.3f}°")
    print(f"  RMS Error:              {np.sqrt(np.mean(error_mags[i]**2)):.3f}")
    print(f"  Max Control Torque:     {np.max(np.abs(u_rec[:, i])):.3f} N·m")
    print(f"  Total Control Effort:   {np.sum(np.abs(u_rec[:, i])) * dt:.3f} N·m·s")
    
    # Find settling time (time to stay within 2° permanently)
    within_threshold = np.abs(angle_errors[i]) < 2.0
    if np.any(within_threshold):
        # Find last time it exceeds threshold
        exceed_indices = np.where(~within_threshold)[0]
        if len(exceed_indices) > 0 and exceed_indices[-1] < len(t_rec) - 100:
            settling_time = t_rec[exceed_indices[-1] + 1]
            print(f"  Settling Time (<2°):    {settling_time:.2f} s")
        else:
            print(f"  Settling Time (<2°):    Not achieved")
    else:
        print(f"  Settling Time (<2°):    Not achieved")

